
UPDATE webhooks SET doc = json_set(json_remove(doc, '$.precondition'), '$.preconditions', json('[{"when":"''X-Gitlab-Event'' in header && body.object_kind == ''note'' && body.object_attributes.noteable_type == ''MergeRequest'' && !body.object_attributes.system && body.object_attributes.note != '''' && body.user.username != ''''","does":"chair","marks":"[body.object_attributes.url.split(''#'')[0], body.merge_request.source_branch]","summary":"body.user.username + '' commented on its merge request''","quote":"body.object_attributes.note","author":"body.user.username"},{"when":"''X-Gitlab-Event'' in header && body.object_kind == ''merge_request'' && body.object_attributes.action in [''merge'', ''close'', ''reopen'']","does":"chair","marks":"[body.object_attributes.url, body.object_attributes.source_branch]","summary":"body.user.username + '' '' + {''merge'': ''merged'', ''close'': ''closed'', ''reopen'': ''reopened''}[body.object_attributes.action] + '' its merge request''"},{"when":"''X-Gitlab-Event'' in header && body.object_kind == ''merge_request'' && body.object_attributes.action == ''approved''","does":"chair","marks":"[body.object_attributes.url, body.object_attributes.source_branch]","summary":"''its merge request is approved (by '' + body.user.username + '')''"},{"when":"''X-Gitlab-Event'' in header && body.object_kind == ''merge_request'' && body.object_attributes.action == ''unapproved''","does":"chair","marks":"[body.object_attributes.url, body.object_attributes.source_branch]","summary":"''its merge request is no longer approved ('' + body.user.username + '' withdrew it)''"},{"when":"''X-Gitlab-Event'' in header && body.object_kind == ''pipeline'' && body.object_attributes.status == ''failed''","does":"chair","marks":"(has(body.merge_request) ? [body.merge_request.url] : []) + [body.object_attributes.ref]","summary":"''pipeline '' + string(int(body.object_attributes.id)) + '' failed on '' + body.object_attributes.ref","quote":"''failed jobs: '' + body.builds.filter(b, b.status == ''failed'').map(b, b.name + '' ('' + b.stage + '')'').join('', '')"}]'))
WHERE json_extract(doc, '$.precondition.kind') = 'gitlab';
UPDATE webhooks SET doc = json_remove(doc, '$.precondition') WHERE json_type(doc, '$.precondition') IS NOT NULL;
